* COBOL Programs Submenu
MAP COBMENU SIZE 24x80
  FIELD AT 1,1  LEN 6  PROT BRIGHT COLOR=GREEN  "MYIF03"
  FIELD AT 1,25 LEN 30 PROT BRIGHT COLOR=GREEN  "COBOL PROGRAMS"
  INPUT DATFLD  AT 1,65 LEN 10 PROT COLOR=GREEN
  STOP          AT 1,75
  FIELD AT 2,1  LEN 8  PROT COLOR=GREEN         "COBMENU0"
  INPUT USRFLD  AT 2,28 LEN 8  PROT COLOR=GREEN
  STOP          AT 2,36
  INPUT TIMFLD  AT 2,65 LEN 8  PROT COLOR=GREEN
  STOP          AT 2,73

  INPUT L01 AT 4,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 4,41
  INPUT L02 AT 5,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 5,41
  INPUT L03 AT 6,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 6,41
  INPUT L04 AT 7,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 7,41
  INPUT L05 AT 8,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 8,41
  INPUT L06 AT 9,3  LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 9,41
  INPUT L07 AT 10,3 LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 10,41
  INPUT L08 AT 11,3 LEN 38 PROT COLOR=TURQUOISE
  STOP      AT 11,41

  INPUT ROLEFLD AT 21,40 LEN 20 PROT COLOR=GREEN
  STOP          AT 21,60
  FIELD AT 21,3  LEN 12 PROT COLOR=GREEN     "SELECTION =>"
  INPUT SELFLD   AT 21,16 LEN 2 UNPROT COLOR=GREEN
  STOP           AT 21,19

  FIELD AT 23,1 LEN 78 PROT COLOR=GREEN  "PF:  1 LOGOFF    3 MAIN MENU    9 HELP                  7 BWD   8 FWD"
  CURSOR AT SELFLD
ENDMAP
